// 테스트용 고심각도 알림 데이터 생성
const testData = {
  alert_type: 'HIGH_SEVERITY_MOISTURE_TEST',
  lot_id: '20250101-TEST01',
  product_name: 'NCM811_양극재_분말_테스트',
  production_line: 'Test-Line-1',
  moisture_measured: 0.75,
  moisture_threshold: 0.50,
  operator: '테스트운전자',
  anomaly_flags: ['exit_humidity_spike', 'res_time_variance_high', 'strong_correlation'],
  timestamp: new Date().toISOString()
};

console.log('🧪 Teams 알림 테스트 데이터 생성:', testData);
return [{ json: testData }];

